 function jump(){if(state!=='playing')return;if(playerY>=ground-PLAYER-2){vy=JUMP;burst(W*.19,playerY,8);tone(460,.09,'triangle',.08)}}
 function end(won){if(state!=='playing')return;state=won?'won':'dead';hud.classList.remove('active');endScreen.classList.remove('hidden');document.getElementById('endEyebrow').textContent=won?'Level complete':'The beat goes on';document.getElementById('endTitle').textContent=won?'YOU SHINE':'CRASHED';document.getElementById('endCopy').textContent=won?'Perfect rhythm. Pulse City is yours.':'Every great run starts with a retry.';const p=won?100:Math.min(99,Math.floor(world/LEVEL_LEN*100));document.getElementById('resultScore').textContent=p+'% COMPLETE';best=Math.max(best,p);localStorage.setItem('neonPulseBest',best);tone(won?880:110,.35,'sawtooth',.09);}
 function burst(x,y,n){for(let i=0;i<n;i++)particles.push({x,y,vx:(Math.random()-.5)*250,vy:(Math.random()-.7)*220,life:.45+Math.random()*.4,size:2+Math.random()*4});}
 function input(e){if(e)e.preventDefault();if(state==='playing'){jump()}else if(state==='dead'||state==='won'){start()} }
-canvas.addEventListener('pointerdown',input);document.getElementById('playBtn').addEventListener('click',start);document.getElementById('retryBtn').addEventListener('click',start);window.addEventListener('keydown',e=>{if(e.code==='Space'||e.code==='ArrowUp'||e.code==='KeyW'){e.preventDefault();if(state==='menu'||state==='dead'||state==='won')start();else jump()}if(e.code==='KeyM')toggleSound()});
+canvas.addEventListener('pointerdown',input);document.getElementById('playBtn').addEventListener('click',start);document.getElementById('retryBtn').addEventListener('click',start);endScreen.addEventListener('pointerdown',e=>{if(!e.target.closest('button'))start()});window.addEventListener('keydown',e=>{if(e.code==='Space'||e.code==='ArrowUp'||e.code==='KeyW'){e.preventDefault();if(state==='menu'||state==='dead'||state==='won')start();else jump()}if(e.code==='KeyM')toggleSound()});
 function toggleSound(){muted=!muted;soundLabel.textContent=muted?'SOUND OFF · 108 BPM':'SOUND ON · 108 BPM';document.getElementById('soundBtn').style.color=muted?'#737b9c':'var(--cyan)';if(!muted)setupAudio()}
 document.getElementById('soundBtn').addEventListener('click',toggleSound);document.getElementById('helpBtn').addEventListener('click',()=>{document.getElementById('endEyebrow').textContent='How to play';document.getElementById('endTitle').textContent='FEEL THE BEAT';document.getElementById('endCopy').textContent='Your cube runs automatically. Tap, click, or press Space to jump over each neon hazard. Land before the next beat.';document.getElementById('resultScore').textContent='108 BPM · 64 BEATS';document.getElementById('retryBtn').textContent='▶  Got it';endScreen.classList.remove('hidden');});
 function frame(now){if(state==='playing'){const dt=Math.min(.04,(now-last)/1000||0);last=now;update(dt);draw(now/1000);if(state==='playing')requestAnimationFrame(frame)}else draw(now/1000)}
 function loop(now){frame(now)}
